(* [comment removed for export] *)
Definition isl_p3_stmt : Prop :=
  forall (r : pv_res) rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3x
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo shi : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (h : hdrv)
    (k j : Z) (mbs tbs : list byte) (j0 j4 jt : list byte) (g : bool),
  isl_ctx m m1 sp (isl_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo shi c pad7 pad2 p0 bs h
          [CB 8 j0; C8 (wz P)] [CB 4 j4; C4 (wz (pv_result_cell r 0))] (p0 + k + j + 2 + pv_adv r) [CB 24 jt]
          (ErrCodeCells (pv_ec r EC_clear)) (pv_cat r g) ->
  isl_pureA sp P IN E lo shi c p0 bs h ->
  bytes_at asegs m1 p0 mbs -> bytes_at asegs m1 (p0 + k + 1) tbs -> Z.of_nat (length mbs) = k -> Z.of_nat (length tbs) = j ->
  1 <= k -> 1 <= j -> p0 + k + j + 2 <= p0 + Z.of_nat (length bs) ->
  r = pv_out (skipn (Z.to_nat (k + j + 2)) bs) ->
  evt asegs (isl_segA_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc P IN E lo shi c pad7 pad2 p0 bs h g m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -160)) gp tp t0 t1 t2 (wz (E + 16)) (wz E) a0 a1 a2 a3 a4 a5 a6 a7
              (wz IN) s3x (wz (p0 + Z.of_nat (length bs))) (wz p0) (wz k) (wz (p0 + k + 1)) (wz j)
              (wz 2147450880) (wz (Z.shiftr IN 3 + 2147450880)) (wz (Z.shiftr (E + 16) 3 + 2147450880)) t3 t4 t5 t6)
        F (Z_to_bv 64 0xcf864) fc None m1 (seg_rom asegs)).

(* [comment removed for export] *)
Local Ltac isl_epilogue SZL SZV :=
  do 13 step;
  lazymatch goal with
  | FRl : rw_cells _ _ (bv_unsigned ?spv + -160) _, VR : rw_cells _ _ (bv_unsigned ?spv + -144) _, ITc : rw_cells _ _ (bv_unsigned ?spv + -136) _,
    TMPc : rw_cells _ _ (bv_unsigned ?spv + -128) _, FRh : rw_cells _ _ (bv_unsigned ?spv + -104) _, ST3 : stk _ _ _ (bv_unsigned ?spv + -160) |- _ =>
      let j1 := fresh "jl" in let F1 := fresh "FRl1" in let j2 := fresh "jv" in let F2 := fresh "VR1" in let j3 := fresh "jt" in let F3 := fresh "TMP1" in
      destruct (rw_cells_forget _ _ _ _ FRl) as [j1 F1]; clear FRl; first [rewrite SZL in F1 | cbn [cells_size csize Nat.add] in F1];
      destruct (rw_cells_forget _ _ _ _ VR) as [j2 F2]; clear VR; first [rewrite SZV in F2 | cbn [cells_size csize Nat.add] in F2];
      destruct (rw_cells_forget _ _ _ _ TMPc) as [j3 F3]; clear TMPc; cbn [cells_size csize Nat.add] in F3;
      join_frameA F1 F2 (bv_unsigned spv + -160); join_frameA F1 ITc (bv_unsigned spv + -160);
      join_frameA F1 F3 (bv_unsigned spv + -160); join_frameA F1 FRh (bv_unsigned spv + -160);
      step; release_frame F1 ST3 (bv_unsigned spv)
  end;
  step.
Scheme kc__5 := Elimination for Corelib.Init.Logic.or Sort Prop.

